local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"Menüs für Spielernamen und Questnamen enthalten nicht mehr die Verknüpfung zum Logfenster. Verschiebe QuestTogether-Logs über das Minikartenmenü oder die Einstellungen zwischen dem Haupt-Chatfenster und einem separaten Fenster."},["title"]="Bereinigung der Kontextmenüs"}},["version"]="6.1.0",["welcome"]="Übersichtlichere Kontextmenüs für Spieler und Quests."},["esES"]={["sections"]={{["items"]={"Los menús de nombre de jugador y nombre de misión ya no incluyen el atajo de la ventana de registro. Mueve los registros de QuestTogether entre la ventana principal del chat y una ventana independiente usando el menú del minimapa o los ajustes."},["title"]="Limpieza de menús contextuales"}},["version"]="6.1.0",["welcome"]="Menús contextuales más claros para jugadores y misiones."},["esMX"]={["sections"]={{["items"]={"Los menús de nombres de jugador y nombres de misiones ya no incluyen el acceso directo a la ventana del registro. Mueve los registros de QuestTogether entre la ventana principal de chat y una ventana separada usando el menú del minimapa o la configuración."},["title"]="Limpieza del menú contextual"}},["version"]="6.1.0",["welcome"]="Menús contextuales más limpios para jugadores y misiones."},["frFR"]={["sections"]={{["items"]={"Les menus de noms de joueurs et de quêtes n’incluent plus le raccourci vers la fenêtre de journal. Déplacez les journaux de QuestTogether entre la fenêtre de discussion principale et une fenêtre séparée via le menu de la minicarte ou les paramètres."},["title"]="Nettoyage des menus contextuels"}},["version"]="6.1.0",["welcome"]="Menus contextuels plus clairs pour les joueurs et les quêtes."},["itIT"]={["sections"]={{["items"]={"I menu dei nomi dei giocatori e delle missioni non includono più la scorciatoia per la finestra del registro. Sposta i registri di QuestTogether tra la finestra principale della chat e una finestra separata usando il menu della minimappa o le impostazioni."},["title"]="Pulizia del menu contestuale"}},["version"]="6.1.0",["welcome"]="Menu contestuali più puliti per giocatori e missioni."},["koKR"]={["sections"]={{["items"]={"플레이어 이름 및 퀘스트 이름 메뉴에 더 이상 로그 창 바로가기가 포함되지 않습니다. 미니맵 메뉴나 설정을 사용해 QuestTogether 로그를 기본 대화창과 별도 창 사이에서 이동할 수 있습니다."},["title"]="상황별 메뉴 정리"}},["version"]="6.1.0",["welcome"]="플레이어와 퀘스트의 상황별 메뉴를 더 깔끔하게 정리했습니다."},["ptBR"]={["sections"]={{["items"]={"Os menus de nome de jogador e de nome de missão não incluem mais o atalho da janela de registros. Mova os registros do QuestTogether entre a janela principal de bate-papo e uma janela separada usando o menu do minimapa ou as configurações."},["title"]="Limpeza do menu de contexto"}},["version"]="6.1.0",["welcome"]="Menus de contexto mais limpos para jogadores e missões."},["ruRU"]={["sections"]={{["items"]={"Меню имен игроков и названий заданий больше не содержат ярлык окна журнала. Перемещайте журналы QuestTogether между основным окном чата и отдельным окном через меню у мини-карты или настройки."},["title"]="Очистка контекстного меню"}},["version"]="6.1.0",["welcome"]="Более чистые контекстные меню для игроков и заданий."},["zhCN"]={["sections"]={{["items"]={"玩家姓名和任务名称菜单不再包含日志窗口快捷项。可使用小地图菜单或设置，在主聊天窗口和单独窗口之间移动 QuestTogether 日志。"},["title"]="右键菜单清理"}},["version"]="6.1.0",["welcome"]="更清爽的玩家和任务右键菜单。"},["zhTW"]={["sections"]={{["items"]={"玩家名稱與任務名稱選單不再包含記錄視窗捷徑。可使用小地圖選單或設定，在主聊天視窗與獨立視窗之間移動 QuestTogether 記錄。"},["title"]="右鍵選單清理"}},["version"]="6.1.0",["welcome"]="玩家與任務的右鍵選單更簡潔。"}}
